// Get the raw string
const raw = $input.first().json.choices[0].message.content;

// Remove the ```json and ``` wrappers
const cleaned = raw.replace(/```json|```/g, '').trim();

// Helper: check if string looks like JSON
const isJsonLike = (str) => /^[\{\[]/.test(str);

// Try to parse JSON, otherwise fall back to plain text handling
let parsed = null;
let email_subject = "";
let email_message = "";

if (isJsonLike(cleaned)) {
  try {
    parsed = JSON.parse(cleaned);
  } catch (e) {
    // If parsing fails, we'll handle as plain text below
    parsed = null;
  }
}

if (parsed && typeof parsed === "object") {
  // Original JSON-based logic
  email_subject = parsed.email_subject ?? "";
  email_message = parsed.email_message ?? "";
} else {
  // Fallback: treat `cleaned` as plain email text
  const lines = cleaned.split("\n");
  const firstLine = lines[0] ?? "";

  if (/^Subject:/i.test(firstLine)) {
    // "Subject: ..." on first line
    email_subject = firstLine.replace(/^Subject:/i, "").trim();
    email_message = lines.slice(1).join("\n").trim();
  } else {
    // No explicit "Subject:", use first line as subject
    email_subject = firstLine.trim();
    email_message = lines.slice(1).join("\n").trim();
  }
}

// Get citation title safely from annotations
const citationTitle =
  $input.first().json.choices[0].message.annotations?.[0]?.url_citation
    ?.title ?? "";

// Replace markdown links [text](url) → <a href="url">TITLE</a>
const fixMarkdownLinks = (text, title) => {
  if (!text) return "";
  return text.replace(
    /\[[^\]]+\]\(([^)]+)\)/g,
    `<a href="$1">${title}</a>`
  );
};

// Clean the email_message
const email_message_fixed = fixMarkdownLinks(email_message, citationTitle);

// Return two separate properties
return {
  email_subject,
  email_message: email_message_fixed,
};

